WITH cleaned AS (SELECT *, TRIM(carrier) AS clean_carrier FROM shipments WHERE order_id IS NOT NULL AND carrier IS DISTINCT FROM 'UPS') SELECT id, order_id, carrier, cost, clean_carrier, MAX(cost) OVER w_grp AS last3_max_cost, SUM(cost) OVER w_grp AS last3_sum_cost, AVG(cost) OVER w_grp AS last3_avg_cost, MIN(cost) OVER w_grp AS last3_min_cost FROM cleaned WHERE YEAR(shipped_date) >= 2025 WINDOW w_grp AS (PARTITION BY status, order_id ORDER BY shipped_date ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)
